package com.sourcetoolkit.app;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.view.*;import android.widget.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;
public class MainActivity extends Activity{
 static final String PREF="source_toolkit",GAME_URI="game_uri";final int BG=0xFF0B0E10,SURFACE=0xFF12171B,LINE=0xFF232B31,BLUE=0xFF2D9CFF,TEXT=0xFFE6EAED,MUTED=0xFF9AA5AD;LinearLayout content;
 int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
 TextView t(String s,int z,int c,boolean b){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(c);if(b)x.setTypeface(Typeface.create("sans-serif-condensed",1));return x;}
 GradientDrawable shape(int c,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(c);if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);render();}
 void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(22),dp(18),dp(16));root.setBackgroundColor(BG);setContentView(root);
 TextView logo=t("SOURCE TOOLKIT",25,TEXT,true);logo.setLetterSpacing(.06f);root.addView(logo);TextView sub=t("GARRY'S MOD  //  SOURCE ENGINE UTILITIES",9,BLUE,false);sub.setLetterSpacing(.16f);root.addView(sub);rule(root,14,14);
 LinearLayout status=new LinearLayout(this);status.setPadding(dp(12),dp(9),dp(8),dp(9));status.setBackgroundColor(SURFACE);View stripe=new View(this);stripe.setBackgroundColor(0xFF73D5AA);status.addView(stripe,new LinearLayout.LayoutParams(dp(2),-1));LinearLayout st=new LinearLayout(this);st.setOrientation(1);st.setPadding(dp(10),0,0,0);boolean ready=getGameUri()!=null;st.addView(t(ready?"就绪":"未设置",12,0xFF73D5AA,true));st.addView(t(ready?"Ready to play (Garry's Mod)":"Select your Garry's Mod folder",12,TEXT,false));status.addView(st);root.addView(status,new LinearLayout.LayoutParams(-1,dp(54)));
 Button mods=button("模组管理  GARRY'S MOD",BLUE,BG);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(48));bp.topMargin=dp(14);root.addView(mods,bp);mods.setOnClickListener(v->openMods());
 LinearLayout pair=new LinearLayout(this);Button choose=button("选择游戏目录…",SURFACE,TEXT),tools=button("工作区设置",SURFACE,TEXT);LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,dp(42),1);half.rightMargin=dp(4);pair.addView(choose,half);LinearLayout.LayoutParams half2=new LinearLayout.LayoutParams(0,dp(42),1);half2.leftMargin=dp(4);pair.addView(tools,half2);root.addView(pair);choose.setOnClickListener(v->pickGame());tools.setOnClickListener(v->settings());
 ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(1);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 section("下载与模组");row("GMod 模组管理器","浏览、启用、禁用、添加和编辑本地模组",this::openMods);row("VTF 转换器","图片转换为 Valve Texture Format",()->placeholder("VTF 转换器","编码器模块尚未接入"));row("VPK 浏览器","查看 VPK 归档目录并导出资源",()->placeholder("VPK 浏览器","VPK 文件浏览模块"));section("本地游戏文件");row("游戏目录","授权访问 Garry's Mod 安装目录",this::pickGame);row("模组工作区","管理 addons 与 addons_disabled",this::openMods);section("设置与工具");row("显示与控制","深色界面 · GDroid 风格",this::settings);row("关于 Source Toolkit","版本 0.1.0 · Android 8.0+",()->placeholder("Source Toolkit","Source Engine utilities"));TextView foot=t("SOURCE TOOLKIT  ·  0.1.0",9,0xFF59636B,false);foot.setPadding(0,dp(18),0,0);content.addView(foot);}
 Button button(String s,int c,int tc){Button b=new Button(this);b.setText(s);b.setTextColor(tc);b.setTextSize(13);b.setAllCaps(false);b.setTypeface(Typeface.create("sans-serif-condensed",1));b.setBackground(shape(c,c==BLUE?0:0xFF38434C));return b;}
 void rule(LinearLayout p,int top,int bottom){View v=new View(this);v.setBackgroundColor(LINE);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,dp(1));q.topMargin=dp(top);q.bottomMargin=dp(bottom);p.addView(v,q);}
 void section(String s){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.addView(t("▪",12,BLUE,true));r.addView(t("  "+s,10,MUTED,false));View line=new View(this);line.setBackgroundColor(LINE);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(1),1);lp.leftMargin=dp(8);r.addView(line,lp);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(28));p.topMargin=dp(8);content.addView(r,p);}
 void row(String title,String desc,Runnable click){LinearLayout r=new LinearLayout(this);r.setOrientation(1);r.setPadding(dp(12),dp(10),dp(4),dp(9));r.addView(t(title,15,TEXT,false));if(desc!=null){TextView d=t(desc,11,MUTED,false);d.setPadding(0,dp(3),0,0);r.addView(d);}TextView arrow=t("›",20,MUTED,false);r.addView(arrow);r.setOnClickListener(v->click.run());content.addView(r);rule(content,0,0);}
 Uri getGameUri(){String s=getSharedPreferences(PREF,0).getString(GAME_URI,null);return s==null?null:Uri.parse(s);}
 void pickGame(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(3|64);startActivityForResult(i,41);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==41&&c==-1&&d!=null){Uri u=d.getData();getContentResolver().takePersistableUriPermission(u,d.getFlags()&3);getSharedPreferences(PREF,0).edit().putString(GAME_URI,u.toString()).apply();render();}}
 void openMods(){if(getGameUri()==null){new AlertDialog.Builder(this).setMessage("请先选择 Garry's Mod 游戏目录。").setPositiveButton("选择目录",(d,w)->pickGame()).setNegativeButton("取消",null).show();return;}startActivity(new Intent(this,GmodModActivity.class));}
 void settings(){new AlertDialog.Builder(this).setTitle("工作区设置").setMessage("固定深色主题。游戏目录使用 Android 文件选择器授权。").setPositiveButton("更改游戏目录",(d,w)->pickGame()).setNegativeButton("关闭",null).show();}
 void placeholder(String a,String b){new AlertDialog.Builder(this).setTitle(a).setMessage(b).setPositiveButton("确定",null).show();}
}